export default function AboutSection({ data }: { data?: any }) {
  const aboutText =
    typeof data?.about?.text === "string" && data.about.text.trim()
      ? data.about.text.trim()
      : "We’re a modern team focused on quality, clarity, and results. Our mission is to help you grow with thoughtful design and reliable delivery.";

  return (
    <section style={{}}>
      <h2>About</h2>
      <p>{aboutText}</p>
    </section>
  );
}

