pages.ServicesSection.tsx:
export default function ServicesSection({ data }: { data?: any }) {
  const services: string[] = Array.isArray(data?.services)
    ? (data.services).map((s) => String(s))
    : [];
  const safeServices =
    services.length > 0
      ? services
      : ["Consulting & Strategy", "Design & Development", "Support & Maintenance"];

  return (
    <section style={{}}>
      <h2>Services</h2>
      <ul>
        {safeServices.map((service, index) => (
          <li key={index}>{service}</li>
        ))}
      </ul>
    </section>
  );
}
